doc:
Given an expression `y : Q($M)` with specified sign (either + or -), construct a proof that
the exponentiation to power `s : ℤ` of (± `y`) (here taking the specified signs) is ± `y ^ s`;
return this proof and the computed sign.

type:
∀ {α : Type u_1} {E : Type u_2} {m : MeasurableSpace α} {p : ENNReal} {μ : MeasureTheory.Measure α}
  [inst : NormedAddCommGroup E] {s : Set α} {hs : MeasurableSet s}
  {hμs : Ne (MeasureTheory.Measure.instFunLike.coe μ s) ENNReal.instTop.top} {c : E},
  Filter.Eventually
    (fun x => Set.instMembership.mem s x → Eq ((MeasureTheory.indicatorConstLp p hs hμs c).val.cast x) c)
    (MeasureTheory.ae μ)

∀ {R : Type u} {α : Type u_1} [inst : Semiring R] [inst_1 : PartialOrder R] {a : R} [inst_2 : Preorder α] {f : α → R}
  [ExistsAddOfLE R] [PosMulStrictMono R] [AddRightStrictMono R] [AddRightReflectLT R],
  StrictMono f → inst_1.lt a 0 → StrictAnti fun x => instHMul.hMul a (f x)

∀ {E : Type u_5} [inst : NormedAddCommGroup E] [inst_1 : NormedSpace Real E] {f g : Real → E}
  {μ : MeasureTheory.Measure Real} {a b : Real},
  Set.EqOn f g (Set.uIcc a b) → Eq (intervalIntegral (fun x => f x) a b μ) (intervalIntegral (fun x => g x) a b μ)

∀ {M : Type u_1} [inst : CommMonoid M] {S : Submonoid M} {N : Type u_2} [inst_1 : CommMonoid N] {P : Type u_3}
  [inst_2 : CommMonoid P] (f : S.LocalizationMap N) {T : Submonoid P} {k : MulEquiv P M}
  (H : Eq (Submonoid.map k.toMonoidHom T) S) (x : P),
  Eq (Submonoid.LocalizationMap.instFunLike.coe (f.ofMulEquivOfDom H) x)
    (Submonoid.LocalizationMap.instFunLike.coe f (EquivLike.toFunLike.coe k x))

∀ {R : Type u} [inst : Monoid R] {A : Type v} {B : Type w} [inst_1 : NonUnitalNonAssocSemiring A]
  [inst_2 : DistribMulAction R A] [inst_3 : NonUnitalNonAssocSemiring B] [inst_4 : DistribMulAction R B] (x : B),
  Eq (NonUnitalAlgHom.instFunLike_1.coe (NonUnitalAlgHom.inr R A B) x) { fst := 0, snd := x }

∀ {α : Type u_1} {s : Finset α} {p : (t : Finset α) → Finset.instPartialOrder.le t s → Prop}
  (motive : (Exists fun t => Exists fun hs => p t ⋯) → Prop) (x : Exists fun t => Exists fun hs => p t ⋯),
  (∀ (t : Finset α) (w : SetLike.instMembership.mem s.powerset t) (hp : p t ⋯), motive ⋯) → motive x

∀ (𝕜 : Type u_1) {E : Type u_2} [inst : RCLike 𝕜] [inst_1 : NormedAddCommGroup E] [InnerProductSpace 𝕜 E]
  [inst : NormedSpace Real E] {G : Type u_4} [inst_2 : NormedAddCommGroup G] [inst_3 : NormedSpace Real G] {f : G → E}
  {s : Set G}, DifferentiableOn Real f s → DifferentiableOn Real (fun y => instHPow.hPow (inst_1.norm (f y)) 2) s

∀ {α : Type u_1} {ι : Type u_2} [inst : MeasurableSpace α] {μ : MeasureTheory.Measure α} {l : Filter ι}
  [inst_1 : LinearOrder α] [inst_2 : TopologicalSpace α] [OrderClosedTopology α] [OpensMeasurableSpace α] {a b : ι → α}
  {A B : α} [MeasureTheory.NullSingletonClass μ],
  Filter.Tendsto a l (nhds A) →
    Filter.Tendsto b l (nhds B) → MeasureTheory.AECover (μ.restrict (Set.Icc A B)) l fun i => Set.Ioo (a i) (b i)

∀ {α : Type u_1} {β : Type u_2} [inst : MeasurableSpace α] [inst_1 : MeasurableSpace β] {μ : MeasureTheory.Measure α}
  {ν : MeasureTheory.Measure β} [hν : MeasureTheory.SFinite ν] [MeasureTheory.SFinite μ] (s : Set α) (t : Set β),
  Eq ((μ.restrict s).prod (ν.restrict t)) ((μ.prod ν).restrict (Set.instSProd.sprod s t))

∀ {M : Type u_1} [inst : Mul M] (toSetoid toSetoid_1 : Setoid M) (e_toSetoid : Eq toSetoid toSetoid_1)
