  Eq { toSetoid := toSetoid, mul' := mul' } { toSetoid := toSetoid_1, mul' := ⋯ }

∀ {n : Nat} (α : Fin (instHAdd.hAdd n 1) → Type u_2) [inst : (i : Fin (instHAdd.hAdd n 1)) → LE (α i)]
  (p : Fin (instHAdd.hAdd n 1)) (f : (i : Fin (instHAdd.hAdd n 1)) → α i),
  Eq (RelIso.instFunLike.coe (RelIso.symm (Fin.insertNthOrderIso α p)) f) { fst := f p, snd := p.removeNth f }

