∀ {α : Type u_1} {E : Type u_4} {m : MeasurableSpace α} {p : ENNReal} {μ : MeasureTheory.Measure α}
  [inst : NormedAddCommGroup E] (f : Subtype fun x => SetLike.instMembership.mem (MeasureTheory.Lp E p μ) x),
