∀ {R₁ : Type u_1} {R₂ : Type u_2} [inst : Semiring R₁] [inst_1 : Semiring R₂] {σ₁₂ : RingHom R₁ R₂} {M₁ : Type u_4}
  {M₂ : Type u_5} [inst_2 : TopologicalSpace M₁] [inst_3 : AddCommMonoid M₁] [inst_4 : Module R₁ M₁]
  [inst_5 : TopologicalSpace M₂] [inst_6 : AddCommMonoid M₂] [inst_7 : Module R₂ M₂] {f : ContinuousLinearMap σ₁₂ M₁ M₂}
  {p : Submodule R₁ M₁} {q : Submodule R₂ M₂}
  (hf :
    ∀ (x : M₁), SetLike.instMembership.mem p x → SetLike.instMembership.mem q (ContinuousLinearMap.funLike.coe f x)),
  Eq (q.subtypeL.comp (f.restrict hf)) (f.domRestrict p)

∀ {ι : Type u_1} {α : Type u_2} {β : Type u_3} [inst : Preorder α] [inst_1 : Preorder β] {Q : ι → Prop} {f : ι → α}
