∀ (n₁ n₂ : Int) (d₁ d₂ : Nat) (hd₁ : Ne d₁ 0) (hd₂ : Ne d₂ 0) (hnd₁ : n₁.natAbs.Coprime d₁)
  (hnd₂ : n₂.natAbs.Coprime d₂) (h₁₂ : n₁.natAbs.Coprime d₂) (h₂₁ : n₂.natAbs.Coprime d₁),
  Eq
    (instHMul.hMul { num := n₁, den := d₁, den_nz := hd₁, reduced := hnd₁ }
      { num := n₂, den := d₂, den_nz := hd₂, reduced := hnd₂ })
    { num := instHMul.hMul n₁ n₂, den := instHMul.hMul d₁ d₂, den_nz := ⋯, reduced := ⋯ }

