  Set.InjOn g (Finset.instSetLike.coe s) → Eq ((Finset.image g s).prod fun x => f x) (s.prod fun x => f (g x))

∀ {M : Type u_1} [inst : CommMonoid M] {S : Submonoid M} {N : Type u_2} [inst_1 : CommMonoid N] {P : Type u_3}
  [inst_2 : CommMonoid P] (f : S.LocalizationMap N) {g : MonoidHom M P}
  (hg : ∀ (y : Subtype fun x => SetLike.instMembership.mem S x), IsUnit (MonoidHom.instFunLike.coe g y.val)),
  Eq (f.lift hg)
    {
      toFun := fun z =>
        instHMul.hMul (MonoidHom.instFunLike.coe g (f.sec z).fst)
          (Units.instInv.inv (MonoidHom.instFunLike.coe (IsUnit.liftRight (g.domRestrict S) hg) (f.sec z).snd)).val,
      map_one' := ⋯, map_mul' := ⋯ }

