  {left_inv : autoParam (Function.LeftInverse invFun toLinearMap.toFun) Equiv.left_inv._autoParam}
  {right_inv : autoParam (Function.RightInverse invFun toLinearMap.toFun) Equiv.right_inv._autoParam}
